// Rebuilds solverWasm.ts from solver.c. Needs clang with the wasm32 target and wasm-ld
// (e.g. LLVM 15+). The generated file is committed, so a normal FacetGL build does not need clang.
//   node src/physics/engine/wasm/build-wasm.mjs
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const out = join(mkdtempSync(join(tmpdir(), 'mmdwasm-')), 'solver.wasm');
execFileSync('clang', [
  '--target=wasm32', '-O2', '-nostdlib', '-ffp-contract=off', '-fno-fast-math', '-mbulk-memory',
  '-Wl,--no-entry', '-Wl,--strip-all', '-Wl,--export-memory', '-Wl,--initial-memory=1048576', '-Wl,--max-memory=1073741824',
  '-o', out, join(here, 'solver.c'),
], { stdio: 'inherit' });
const b64 = readFileSync(out).toString('base64');
writeFileSync(join(here, 'solverWasm.ts'),
  `// GENERATED by build-wasm.mjs from solver.c — do not edit.\nexport const SOLVER_WASM_BASE64 =\n  '${b64}';\n`);
console.log('solverWasm.ts written,', Buffer.from(b64, 'base64').length, 'bytes');
